"""Stile QSS ripreso da IZI Retrieve, senza modificare forme e dimensioni dei controlli."""
QSS = "\n* {\n    font-family: \"Adobe Clean\", \"Inter\", \"Segoe UI Variable\", \"Segoe UI\",\n                 \"SF Pro Text\", \".AppleSystemUIFont\", \"Helvetica Neue\", Arial;\n    font-size: 12px;\n    color: #D4D4D4;\n}\nQMainWindow, #root { background: #1E1E1E; }\nQWidget { background: transparent; }\n\n#titleBar { background: #2B2B2B; }\n#titleLabel { color: #B4B4B4; font-size: 12px; font-weight: 600; letter-spacing: 0.5px; }\n\n#panel { background: #323232; border: none; }\n#panelTitle {\n    background: #2B2B2B; color: #9A9A9A; font-size: 11px; font-weight: 600;\n    letter-spacing: 1px; padding: 8px 12px;\n}\n#sectionLabel { color: #9A9A9A; font-size: 11px; font-weight: 600; letter-spacing: 1px; }\n#hint { color: #8A8A8A; font-size: 11px; }\n#warn { color: #D0AD7C; font-size: 11px; }\n#status { color: #B4B4B4; }\n#pathPreview { color: #E6E6E6; }\n#bottomBar { background: #2B2B2B; }\n#footer { color: #7A7A7A; font-size: 10px; letter-spacing: 0.5px; }\n\nQLineEdit, QPlainTextEdit, QListWidget {\n    background: #1E1E1E; border: 1px solid #1E1E1E; border-radius: 2px;\n    padding: 5px 8px; selection-background-color: #4A6499; selection-color: white;\n}\nQLineEdit:focus, QPlainTextEdit:focus { border: 1px solid #7896D0; }\nQLineEdit:disabled { background: #2A2A2A; color: #6E6E6E; border-color: #2A2A2A; }\nQPlainTextEdit { font-family: \"Cascadia Mono\", \"SF Mono\", Menlo, Consolas, monospace; font-size: 12px; }\nQListWidget { padding: 2px; outline: 0; }\nQListWidget::item { padding: 4px 6px; border-radius: 2px; }\nQListWidget::item:selected { background: #3F4F63; color: white; }\nQListWidget::item:hover { background: #2D2D2D; }\n\nQPushButton {\n    background: #535353; border: none; border-radius: 13px;\n    padding: 6px 16px; color: #F0F0F0;\n}\nQPushButton:hover { background: #646464; }\nQPushButton:pressed { background: #474747; }\nQPushButton:disabled { background: #3C3C3C; color: #737373; }\nQPushButton#primary { background: #7896D0; color: #14181F; font-weight: 600; padding: 7px 26px; }\nQPushButton#primary:hover { background: #8DA8DB; }\nQPushButton#primary:pressed { background: #6482BC; }\nQPushButton#primary:disabled { background: #3A4254; color: #8A91A0; }\nQPushButton#ghost { background: transparent; border: 1px solid #5E5E5E; }\nQPushButton#ghost:hover { background: #3C3C3C; }\nQPushButton#ghost:disabled { border-color: #444; }\n\nQCheckBox, QRadioButton { spacing: 8px; padding: 2px 0; }\nQCheckBox:disabled, QRadioButton:disabled { color: #6E6E6E; }\nQCheckBox::indicator {\n    width: 14px; height: 14px; border: 1px solid #6B6B6B; border-radius: 2px; background: #1E1E1E;\n}\nQCheckBox::indicator:hover { border-color: #9A9A9A; }\nQCheckBox::indicator:checked { background: #7896D0; border-color: #7896D0;  }\nQCheckBox::indicator:disabled { border-color: #4A4A4A; background: #2A2A2A; }\nQCheckBox::indicator:checked:disabled { background: #4A5560; border-color: #4A5560; }\n\nQRadioButton::indicator {\n    width: 14px; height: 14px; border: 1px solid #6B6B6B; border-radius: 8px; background: #1E1E1E;\n}\nQRadioButton::indicator:hover { border-color: #9A9A9A; }\nQRadioButton::indicator:checked {\n    border: 1px solid #7896D0;\n    background: qradialgradient(cx:0.5, cy:0.5, radius:0.5, fx:0.5, fy:0.5,\n                stop:0 #FFFFFF, stop:0.36 #FFFFFF, stop:0.42 #7896D0, stop:1 #7896D0);\n}\nQRadioButton::indicator:disabled { border-color: #4A4A4A; background: #2A2A2A; }\nQRadioButton::indicator:checked:disabled {\n    border: 1px solid #4A4A4A;\n    background: qradialgradient(cx:0.5, cy:0.5, radius:0.5, fx:0.5, fy:0.5,\n                stop:0 #8A8A8A, stop:0.36 #8A8A8A, stop:0.42 #4A5560, stop:1 #4A5560);\n}\n\nQTabWidget::pane { border: none; border-top: 1px solid #1E1E1E; }\nQTabBar::tab {\n    background: transparent; color: #9A9A9A; padding: 8px 14px;\n    border-bottom: 2px solid transparent; margin-right: 2px;\n}\nQTabBar::tab:hover { color: #E0E0E0; }\nQTabBar::tab:selected { color: white; border-bottom: 2px solid #7896D0; }\n\nQProgressBar { background: #1E1E1E; border: none; border-radius: 3px; max-height: 6px; min-height: 6px; }\nQProgressBar::chunk { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #7896D0, stop:1 #D0AD7C); border-radius: 3px; }\n\nQScrollBar:vertical { background: transparent; width: 10px; margin: 0; }\nQScrollBar::handle:vertical { background: #4A4A4A; border-radius: 5px; min-height: 28px; margin: 1px; }\nQScrollBar::handle:vertical:hover { background: #5E5E5E; }\nQScrollBar:horizontal { background: transparent; height: 10px; margin: 0; }\nQScrollBar::handle:horizontal { background: #4A4A4A; border-radius: 5px; min-width: 28px; margin: 1px; }\nQScrollBar::handle:horizontal:hover { background: #5E5E5E; }\nQScrollBar::add-line, QScrollBar::sub-line { width: 0; height: 0; }\nQScrollBar::add-page, QScrollBar::sub-page { background: transparent; }\n\n/* menu del tasto destro: più scuro dei pannelli (#323232) ma non nero, testo ben leggibile */\nQMenu {\n    background: #2A2A2A; border: 1px solid #5A5A5A; padding: 4px 0;\n}\nQMenu::item {\n    background: transparent; color: #ECECEC; padding: 6px 34px 6px 16px; margin: 0 4px;\n    border-radius: 3px; font-size: 12px;\n}\nQMenu::item:selected { background: #4A6499; color: #FFFFFF; }\nQMenu::item:disabled { color: #7C7C7C; background: transparent; }\nQMenu::separator { height: 1px; background: #4A4A4A; margin: 4px 10px; }\nQMenu::right-arrow { width: 8px; height: 8px; }\n\n#aboutName { color: #F1F1EF; font-size: 22px; font-weight: 600; }\n#aboutSub { color: #D0AD7C; font-size: 13px; }\n#suiteName { color: #F1F1EF; font-size: 13px; font-weight: 600; }\n#badge { color: #D0AD7C; border: 1px solid #D0AD7C; border-radius: 10px; padding: 2px 10px; font-size: 11px; }\nQPlainTextEdit#notes { font-family: inherit; font-size: 12px; }\nQDialog#dlg { background: #323232; border: 1px solid #5A5A5A; }\nQToolTip { background: #2A2A2A; color: #ECECEC; border: 1px solid #5A5A5A; padding: 4px; }\n"
